document.addEventListener("DOMContentLoaded",function(){if(typeof EF==="undefined"||!EF.click){console.warn("Everflow not loaded");return}EF.click({offer_id:EF.urlParameter("oid"),affiliate_id:EF.urlParameter("affid"),source_id:EF.urlParameter("source_id"),sub1:EF.urlParameter("sub1"),sub2:EF.urlParameter("sub2"),sub3:EF.urlParameter("sub3"),sub4:EF.urlParameter("sub4"),sub5:EF.urlParameter("sub5"),uid:EF.urlParameter("uid")}).then(function(t){if(!t){console.warn("No Everflow TID returned");return}console.log("Everflow TID:",t);document.querySelectorAll(".area-kits a").forEach(function(l){try{var u=new URL(l.href,window.location.origin);u.searchParams.set("sub5",t);l.href=u.toString()}catch(e){console.warn("Invalid URL:",l.href)}})}).catch(function(e){console.error("Everflow click error:",e)})});
 